'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Image from 'next/image'

const ANCHOR_QUESTIONS = [
  {
    id: 1,
    question: 'Which of these feels most like home?',
    images: [
      { id: 'a', src: 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=400', label: 'Modern & Clean' },
      { id: 'b', src: 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=400', label: 'Warm & Cozy' },
      { id: 'c', src: 'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?w=400', label: 'Bold & Dramatic' },
      { id: 'd', src: 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=400', label: 'Light & Airy' },
    ]
  },
]

export default function Step2Page() {
  const router = useRouter()
  const [currentQuestion, setCurrentQuestion] = useState(0)
  const [selected, setSelected] = useState<string | null>(null)

  const question = ANCHOR_QUESTIONS[currentQuestion]

  useEffect(() => {
    if (typeof window !== 'undefined') {
      console.log(JSON.stringify({ __COVA__: true, event: 'page:mount', data: { page: 'step-2' }, ts: Date.now(), url: '/design/step-2' }))
    }
  }, [])

  const handleSelect = (id: string) => {
    setSelected(id)
    setTimeout(() => {
      router.push('/design/step-3')
    }, 400)
  }

  return (
    <div className="min-h-screen bg-[#0d1b2a] text-white flex flex-col">
      {/* Header */}
      <header className="flex items-center justify-between px-6 py-4 border-b border-white/10">
        <button
          onClick={() => router.back()}
          className="w-9 h-9 rounded-full border border-white/30 flex items-center justify-center text-white/70 hover:text-white"
        >
          ‹
        </button>
        <h1 className="text-[#c9a84c] text-2xl font-serif tracking-widest">Cova</h1>
        <span className="text-white/50 text-sm tracking-widest">STEP 2 OF 4</span>
      </header>

      {/* Progress bar */}
      <div className="w-full h-px bg-white/10">
        <div className="h-px bg-[#c9a84c]" style={{ width: '50%' }} />
      </div>

      {/* Content */}
      <main className="flex-1 flex flex-col items-center justify-center px-6 py-12">
        <p className="text-[#c9a84c] text-xs tracking-[0.2em] uppercase mb-4">
          Question {currentQuestion + 1} of 3
        </p>
        <h2 className="text-4xl md:text-5xl font-serif text-center mb-3">
          {question.question}
        </h2>
        <p className="text-white/50 mb-10">Pick the one that resonates most.</p>

        {/* 2x2 Image Grid */}
        <div className="grid grid-cols-2 gap-4 w-full max-w-2xl">
          {question.images.map((img) => (
            <button
              key={img.id}
              onClick={() => handleSelect(img.id)}
              className={`relative aspect-square rounded-2xl overflow-hidden border-2 transition-all ${
                selected === img.id
                  ? 'border-[#c9a84c] scale-95'
                  : 'border-transparent hover:border-white/30'
              }`}
            >
              <Image
                src={img.src}
                alt={img.label}
                fill
                className="object-cover"
                unoptimized
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
              <span className="absolute bottom-3 left-3 text-sm font-medium">{img.label}</span>
            </button>
          ))}
        </div>
      </main>
    </div>
  )
}
